import mysql.connector
from mysql.connector import Error
import logging

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def get_employee_threshold_db_config():
    # Configuration for database connection
    return {
        'user': 'your_username',
        'password': 'your_password',
        'host': 'your_host',
        'database': 'your_database'
    }

def convert_threshold_to_int(threshold):
    try:
        return int(threshold)
    except ValueError:
        logger.error("Threshold must be an integer")
        raise

def get_employees_above_threshold(threshold):
    db_config = get_employee_threshold_db_config()
    try:
        conn = mysql.connector.connect(**db_config)
        cursor = conn.cursor()
        threshold = convert_threshold_to_int(threshold)
        query = "SELECT * FROM employees WHERE salary > %s"
        cursor.execute(query, (threshold,))
        employees = cursor.fetchall()
        cursor.close()
        conn.close()
        return employees
    except Error as e:
        logger.error(f"Error getting employees: {e}")
        raise

def get_threshold():
    query = "SELECT threshold FROM config WHERE name = 'salary_threshold'"
    db_config = get_employee_threshold_db_config()
    try:
        conn = mysql.connector.connect(**db_config)
        cursor = conn.cursor()
        cursor.execute(query)
        result = cursor.fetchone()
        cursor.close()
        conn.close()
        if result:
            return result[0]
        else:
            logger.error("Threshold not found in database")
            raise
    except Error as e:
        logger.error(f"Error getting threshold: {e}")
        raise

def main():
    threshold = get_threshold()
    try:
        employees = get_employees_above_threshold(threshold)
        for employee in employees:
            print(employee)
    except Exception as e:
        logger.error(f"Error processing threshold: {e}")

import mysql.connector

class GameModeLeaderboard:
    def __init__(self, db_connection):
        self.db_connection = db_connection

    def get_leaderboard(self, game_mode_name):
        cursor = self.db_connection.cursor()
        query = ("SELECT * FROM leaderboard "
                 "WHERE game_mode_name = %s "
                 "ORDER BY score DESC")
        cursor.execute(query, (game_mode_name,))
        return cursor.fetchall()
